```python
def fib4(n: int) -> int:
    """Compute the n-th element of the fib4 number sequence efficiently without recursion."""
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initial base values for n=0,1,2,3
    a, b, c, d = 0, 0, 2, 0  # fib4(0), fib4(1), fib4(2), fib4(3)

    for _ in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

# Example usage
if __name__ == "__main__":
    print(fib4(5))  # 4
    print(fib4(6))  # 8
    print(fib4(7))  # 14
```

