def get_closest_vowel(word):
    vowels = set("aeiouAEIOU")

    # Find the rightmost vowel that is between two consonants
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if the character before and after are consonants
            if word[i-1].lower() not in "aeiou" and word[i+1].lower() not in "aeiou":
                return word[i]

    return ""
