def compare_one(a, b):
    # Helper to convert string with comma or dot to float
    def to_number(value):
        if isinstance(value, str):
            # Replace comma with dot for uniform conversion
            value = value.replace(",", ".")
            return float(value)
        return float(value)

    # Convert both to numbers for comparison
    num_a = to_number(a)
    num_b = to_number(b)

    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None
